set local role service_role;
do $$ declare actor uuid := '71000000-0000-4000-8000-000000000010'; org uuid := '71000000-0000-4000-8000-000000000001'; dario uuid := '71000000-0000-4000-8000-000000000020'; anna uuid := '71000000-0000-4000-8000-000000000021'; van uuid := '71000000-0000-4000-8000-000000000030'; result jsonb; current jsonb; failed boolean; begin
 result:=public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-15','idempotency_key','71000000-0000-4000-8000-000000000040','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van,'route','33','departure_order',33,'departure_group',1,'parking_lot_position',0,'departure_wave',1),jsonb_build_object('driver_id',anna,'work_status','TURNO','vehicle_id','71000000-0000-4000-8000-000000000031','route','34','departure_order',34,'departure_group',2,'parking_lot_position',0,'departure_wave',2))));
 assert result->>'idempotent'='false','first confirmation';
 current:=public.internal_read_current_operational_day(org,'2030-09-15'); assert current->'rows'->0->>'driver_first_name_snapshot'='Dario','driver snapshot'; assert current->'rows'->0->>'vehicle_plate_snapshot'='AB123CD','vehicle snapshot'; assert current->'rows'->0->>'route_snapshot'='33','route snapshot'; assert current->'rows'->0->>'departure_order'='33','global order starts at 33'; assert current->'rows'->1->>'departure_order'='34','global order continues across group and wave'; assert current->'rows'->0->>'parking_lot_position'='0' and current->'rows'->1->>'parking_lot_position'='0','parking lot position may repeat'; assert current->'rows'->0->>'departure_group'='1' and current->'rows'->1->>'departure_group'='2','group is descriptive'; assert current->'rows'->0->>'departure_wave'='1' and current->'rows'->1->>'departure_wave'='2','wave is descriptive';
 result:=public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-15','idempotency_key','71000000-0000-4000-8000-000000000040','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van)))); assert result->>'idempotent'='true','idempotent retry';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-15','idempotency_key','71000000-0000-4000-8000-000000000041','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van)))); exception when others then failed:=SQLERRM='OPERATIONAL_DAY_ALREADY_CONFIRMED'; end; assert failed,'second confirmation rejected';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-16','idempotency_key','71000000-0000-4000-8000-000000000042','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van),jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id','71000000-0000-4000-8000-000000000031')))); exception when others then failed:=SQLERRM='OPERATIONAL_DRIVER_DUPLICATE'; end; assert failed,'driver duplicate rejected';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-16','idempotency_key','71000000-0000-4000-8000-000000000043','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van),jsonb_build_object('driver_id',anna,'work_status','TURNO','vehicle_id',van)))); exception when others then failed:=SQLERRM='OPERATIONAL_VEHICLE_DUPLICATE'; end; assert failed,'vehicle duplicate rejected';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-16','idempotency_key','71000000-0000-4000-8000-000000000047','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id',van,'departure_order',1),jsonb_build_object('driver_id',anna,'work_status','TURNO','vehicle_id','71000000-0000-4000-8000-000000000031','departure_order',1)))); exception when others then failed:=SQLERRM='OPERATIONAL_DEPARTURE_ORDER_DUPLICATE'; end; assert failed,'departure order duplicate rejected';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-16','idempotency_key','71000000-0000-4000-8000-000000000044','rows',jsonb_build_array(jsonb_build_object('driver_id',anna,'work_status','FERIE','vehicle_id',van,'departure_group',1,'parking_lot_position',0,'departure_wave',1)))); exception when others then failed:=SQLERRM='OPERATIONAL_ABSENCE_FIELDS_FORBIDDEN'; end; assert failed,'absence descriptive fields and vehicle rejected';
 result:=public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CORRECT','correction_reason','Mezzo corretto','operating_date','2030-09-15','idempotency_key','71000000-0000-4000-8000-000000000045','rows',jsonb_build_array(jsonb_build_object('driver_id',dario,'work_status','TURNO','vehicle_id','71000000-0000-4000-8000-000000000031','route','34','departure_order',33,'departure_group',1,'parking_lot_position',0,'departure_wave',1),jsonb_build_object('driver_id',anna,'work_status','RIPOSO')))); assert result->'day'->>'revision'='2','new correction revision'; perform 1 from public.checkvan_operational_days where organization_id=org and operating_date='2030-09-15' and revision=1 and status='superseded'; assert found,'original preserved';
 failed:=false; begin perform public.internal_admin_confirm_operational_day(actor,org,jsonb_build_object('action','CONFIRM','operating_date','2030-09-17','idempotency_key','71000000-0000-4000-8000-000000000046','rows',jsonb_build_array(jsonb_build_object('driver_id','71000000-0000-4000-8000-000000000022','work_status','TURNO','vehicle_id',van)))); exception when others then failed:=SQLERRM='OPERATIONAL_DRIVER_NOT_FOUND'; end; assert failed,'organization isolation';
 assert not has_table_privilege('authenticated','public.checkvan_operational_days','SELECT'),'direct client denied'; assert (select relrowsecurity from pg_class where oid='public.checkvan_operational_days'::regclass),'RLS enabled'; raise notice 'PASS: operational history global order, descriptive departure fields, idempotency, isolation, duplicates, correction and no direct client access'; end $$;
